package com.rpis.backend.model;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * One line of a Terminal Report list section (table of contents, list of tables, figures,
 * graphs, appendices, acronyms).
 *
 * <p>{@code label} is the entry itself (a section title, a table title, an acronym) and
 * {@code detail} the optional second part (the meaning of an acronym, the description of an
 * appendix). {@code page} is the page number the proponent entered; it stays empty when the
 * proponent did not provide one - no page number is ever generated by the system.</p>
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class TerminalReportEntry {

    private String label;
    private String detail;
    private String page;
}
